Arguments: {"title":"Find pushchair models on Silver Cross site","cwd":null,"code":"const tabId = 787783793;

const pushchairs = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/products/"]'));
  const results = [];
  const seen = new Set();
  for (const a of links) {
    const text = a.textContent.trim().replace(/\s+/g, ' ');
    const href = a.href;
    if (seen.has(href)) continue;
    if (href.includes('reef') || href.includes('wave') || href.includes('tide') || href.includes('dune') || href.includes('clic') || href.includes('jet') || href.includes('pop') || href.includes('kensington') || href.includes('balmoral')) {
      seen.add(href);
      results.push({ href, text });
    }
  }
  return results;
});

console.log("Filtered strollers:", pushchairs);
"}
